const todoSchema = {
	type: "object",
	required: ["userId", "id", "title", "completed"],
	properties: {
		userId: { type: "integer" },
		id: { type: "integer" },
		title: { type: "string" },
		completed: { type: "boolean" }
	}
}

pm.test("Response matching the Todo schema", () => {
	pm.response.to.have.jsonSchema({
		type: "array",
		items: todoSchema
	});
});

