pm.test("Status 200", () => {
	pm.response.to.have.status(200);
});

const todos = pm.response.json();

pm.test("Response is a non-empty array", () => {
	pm.expect(todos).to.be.an("array").that.is.not.empty;
});

pm.test("Every todo has userId = 1 and completed = false", () => {
	todos.forEach((todo, index) => {
		console.log(`Todo at index ${index}:`, todo);
		pm.expect(todo.userId, `Todo at index ${index}: userId`).to.equal(1);

		pm.expect(todo.completed, `Todo at index ${index}: completed`).to.equal(false);
	});
});

pm.test("Status 201 Created", () => {
	pm.response.to.have.status(201);
});

const created = pm.response.json();
const requestBody = JSON.parse(pm.request.body.raw.replace("{{todoTitle}}", pm.collectionVariables.get("todoTitle")))

pm.test("Response data matches the request body", () => {
	pm.expect(created.userId).to.equal(requestBody.userId);
	pm.expect(created.title).to.equal(requestBody.title);
	pm.expect(created.completed).to.equal(requestBody.completed);
});

pm.test("Response has a valid ID and saves it as todoId", () => {
	pm.expect(created.id).to.be.a("number");
	pm.expect(Number.isInteger(created.id)).to.equal(true);
	pm.expect(created.id).to.be.above(0);

	pm.collectionVariables.set("todoId", created.id);
});

console.log("Created todo:", created);

